def _canonical(value):
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )


def _sha(value):
    return hashlib.sha256(_canonical(value).encode("utf-8")).hexdigest()


def _source(name):
    return gzip.decompress(base64.b64decode(_SOURCES[name]))


def _install(name):
    module = types.ModuleType(name)
    module.__file__ = f"<embedded:{name}>"
    module.__package__ = ""
    sys.modules[name] = module
    exec(compile(_source(name), module.__file__, "exec"), module.__dict__)
    return module


def _ensure_flint():
    try:
        import flint
        if getattr(flint, "__version__", None) != "0.8.0":
            raise ImportError("wrong python-flint version")
    except (ImportError, ModuleNotFoundError):
        print("[install] python-flint==0.8.0", flush=True)
        subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "-q",
                "python-flint==0.8.0",
            ],
            check=True,
        )


def _run(module, argv):
    previous = sys.argv[:]
    try:
        sys.argv = [module.__file__, *argv]
        module.main()
    finally:
        sys.argv = previous


def _load(path):
    return json.loads(path.read_text(encoding="utf-8"))


def _same(first, second):
    return first.read_bytes() == second.read_bytes()


def main():
    print(
        "[start] L4 reproducible-certificate audit v1.3; "
        "two full formal runs will be compared...",
        flush=True,
    )
    _ensure_flint()
    _install("pasqal_two_atom_matched_fibre_test")
    _install("pasqal_two_atom_q2_prospective_ranking")
    _install("pasqal_L4_arb_formal_audit")
    kraw = _install("pasqal_L4_exact_fibre_krawczyk_audit_v1_3")
    ordering = _install("pasqal_L4_exact_root_ordering_audit_v1_3")

    root = Path("pasqal_L4_reproducible_v1_3_results")
    inputs = root / "inputs"
    inputs.mkdir(parents=True, exist_ok=True)
    cohort_path = inputs / "cohort.json"
    frozen_path = inputs / "frozen_order30_certificate.json"
    cohort_path.write_text(
        json.dumps(_DATA["cohort"], indent=2), encoding="utf-8"
    )
    frozen_path.write_text(
        json.dumps(_DATA["frozen_ordering"], indent=2), encoding="utf-8"
    )

    for label in ("repro_A", "repro_B"):
        run_root = root / label
        kraw_dir = run_root / "krawczyk"
        ordering_dir = run_root / "ordering"
        _run(
            kraw,
            [
                "--cohort",
                str(cohort_path),
                "--box-radius",
                "3e-12",
                "--max-paths",
                "12",
                "--output-dir",
                str(kraw_dir),
            ],
        )
        _run(
            ordering,
            [
                "--krawczyk-certificate",
                str(kraw_dir / "krawczyk_certificate.json"),
                "--ordering-certificate",
                str(frozen_path),
                "--output-dir",
                str(ordering_dir),
            ],
        )

    proof_files = (
        "krawczyk/protocol.json",
        "krawczyk/krawczyk_certificate.json",
        "krawczyk/report.json",
        "ordering/protocol.json",
        "ordering/exact_root_ordering_certificate.json",
        "ordering/report.json",
    )
    comparisons = {
        relative: _same(
            root / "repro_A" / relative,
            root / "repro_B" / relative,
        )
        for relative in proof_files
    }
    byte_identical = all(comparisons.values())

    kraw_report = _load(root / "repro_A/krawczyk/report.json")
    ordering_report = _load(root / "repro_A/ordering/report.json")
    kraw_protocol = _load(root / "repro_A/krawczyk/protocol.json")
    summary = {
        "scientific_status": (
            "L4_REPRODUCIBLE_CERTIFICATE_SUPPORTED"
            if byte_identical
            and kraw_report["scientific_status"]
            == "L4_EXACT_RESPONSE_FIBRE_KRAWCZYK_SUPPORTED"
            and ordering_report["scientific_status"]
            == "L4_EXACT_ROOT_DIRECT_FINITE_ERROR_ORDERING_SUPPORTED"
            else "L4_REPRODUCIBLE_CERTIFICATE_INCONCLUSIVE"
        ),
        "formal_interval_arithmetic": True,
        "arb_precision_bits": 192,
        "fixed_box_radius": 3e-12,
        "two_run_proof_files_byte_identical": byte_identical,
        "proof_file_comparisons": comparisons,
        "frozen_cohort_sha256": kraw_protocol["frozen_cohort_sha256"],
        "krawczyk_protocol_sha256": kraw_report["protocol_sha256"],
        "krawczyk_certificate_sha256": (
            kraw_report["krawczyk_certificate_sha256"]
        ),
        "ordering_protocol_sha256": ordering_report["protocol_sha256"],
        "ordering_certificate_sha256": (
            ordering_report["exact_root_ordering_certificate_sha256"]
        ),
        "krawczyk_inclusions": sum(
            bool(row["krawczyk_inclusion_pass"])
            for row in kraw_report["paths"]
        ),
        "direct_certified_pairs": ordering_report[
            "direct_certified_pairs"
        ],
        "possible_pairs": ordering_report["possible_pairs"],
        "order30_certified_pairs": ordering_report[
            "order30_certified_pairs"
        ],
        "order30_incorrect_certified_pairs": ordering_report[
            "order30_incorrect_certified_pairs"
        ],
        "claim_boundary": (
            "Serialized two-atom model only; not PASQAL hardware, "
            "calibration, model-discrepancy, or QPU evidence."
        ),
    }
    summary_path = root / "reproducibility_summary.json"
    summary_path.write_text(
        json.dumps(summary, indent=2), encoding="utf-8"
    )

    final_root = root / "certificates"
    destinations = {
        "krawczyk": final_root / "exact_fibre_krawczyk",
        "ordering": final_root / "exact_root_ordering",
    }
    for destination in destinations.values():
        destination.mkdir(parents=True, exist_ok=True)
    for filename in (
        "protocol.json",
        "krawczyk_certificate.json",
        "report.json",
    ):
        shutil.copy2(
            root / "repro_A/krawczyk" / filename,
            destinations["krawczyk"] / filename,
        )
    for filename in (
        "protocol.json",
        "exact_root_ordering_certificate.json",
        "report.json",
    ):
        shutil.copy2(
            root / "repro_A/ordering" / filename,
            destinations["ordering"] / filename,
        )
    shutil.copy2(cohort_path, final_root / "cohort.json")
    shutil.copy2(summary_path, final_root / "reproducibility_summary.json")

    print("=" * 116)
    print("PASQAL L4 REPRODUCIBLE CERTIFICATE AUDIT v1.3")
    print("=" * 116)
    print(json.dumps(summary, indent=2))
    print("\nInterpretation")
    if summary["scientific_status"].endswith("_SUPPORTED"):
        print(
            "  PASS: two independent formal runs produced byte-identical "
            "protocols, certificates, and reports."
        )
        print(
            "  PRIMARY L4: Krawczyk 12/12 and direct finite-error ordering "
            "66/66."
        )
        print(
            "  SECONDARY MECHANISM: order-30 certifies 52/66 with zero "
            "certified reversals."
        )
    else:
        print(
            "  INCONCLUSIVE: at least one scientific or reproducibility "
            "gate failed. Do not publish the generated certificate set."
        )
    print(f"  Output directory: {root}")


if __name__ == "__main__":
    main()
